```python
import time
import functools

def retry(times=3, delay=1.0, log=[]):
    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            percobaan = 0
            while percobaan < times:
                try:
                    return fn(*args, **kwargs)
                except Exception as e:
                    percobaan += 1
                    log.append(f'{fn.__name__} gagal ke-{percobaan}: {e}')
                    if percobaan < times:
                        time.sleep(delay)
            return None
        return wrapper
    return decorator

